<script setup lang="ts">import Table from './common/Table.vue';import Status from './common/Status.vue';import {fmt} from '../utils/format';defineProps<{runs:any[]}>();defineEmits(['open']);function marks(r:any){return (r.trace_snapshot||[]).reduce((n:number,t:any)=>n+(t.constraints?.length||0),0)}function conflicted(r:any){return r.result?.constraint_conflicts?.length||0}</script><template><Table :headers="['推断研究','状态','固定模型/轨迹数','标记时刻 / 冲突轨迹','无约束总logL','打开']"><tr v-for="r in runs" :key="r.id"><td><strong>{{r.name}}</strong><small>#{{r.id}} / 研究{{r.study_id}}</small></td><td><Status :value="r.status"/><small v-if="r.error" class="copper">{{r.error}}</small></td><td>{{r.profile_snapshot.name}}<small>{{r.trace_snapshot.length}}条</small></td><td>{{marks(r)}} 处<small v-if="conflicted(r)" class="copper">冲突轨迹 {{conflicted(r)}}</small></td><td>{{r.total_log_likelihood===null?'—':fmt(r.total_log_likelihood,5)}}</td><td><button @click="$emit('open',r)">展开隐态 ↗</button></td></tr></Table></template>
